// Package tensor holds the float32 numeric kernels behind the layago encoder:
// a tiled, parallel GEMM over nn.Linear-layout weights with an optional int8
// weight path, and the element-wise operations a ModernBERT/Laya forward pass
// needs.
//
// The GEMM has a portable Go kernel (this file), which is the fallback and
// the oracle, and assembly microkernels for arm64 NEON and amd64 AVX2+FMA
// (kernel.go, gemm_*.s, generated by ./asmgen) selected per call through
// Parallel.Kernel. The purego build tag removes the assembly. Everything
// else is portable Go (CGO_ENABLED=0).
//
// Output is bit-identical for a given GOARCH, GOAMD64 level and kernel
// regardless of the worker count or a row's position in the batch, because
// every output element is one sequential dot product over K computed by
// exactly one goroutine, and an element always takes the same code path. The
// Go specification allows the compiler to fuse a*b+c, which it does on arm64
// and on amd64 v3, so results can differ between architectures and kernels
// within floating-point tolerance; see Kernel for when kernels agree exactly.
package tensor

import (
	"fmt"
	"math"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Parallel controls how one operation runs: intra-op parallelism (Workers
// <= 0 means GOMAXPROCS) and the GEMM microkernel (the zero value,
// KernelAuto, picks the best one this CPU supports).
type Parallel struct {
	Workers int
	Kernel  Kernel
}

// N returns the effective worker count.
func (p Parallel) N() int {
	if p.Workers > 0 {
		return p.Workers
	}
	return runtime.GOMAXPROCS(0)
}

// Run calls fn(task) for every task in [0, tasks), spreading tasks over up to
// N goroutines. Tasks are claimed dynamically, so fn must not depend on which
// goroutine runs it. Every goroutine running tasks yields its processor
// between two tasks once it has run for yieldAfter without yielding (see
// yielder), so inference shares a busy processor at sub-millisecond grain.
func (p Parallel) Run(tasks int, fn func(task int)) {
	workers := p.N()
	if workers > tasks {
		workers = tasks
	}
	if workers <= 1 {
		y := newYielder()
		for i := 0; i < tasks; i++ {
			fn(i)
			y.between()
		}
		return
	}
	var next atomic.Int64
	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			y := newYielder()
			for {
				i := int(next.Add(1) - 1)
				if i >= tasks {
					return
				}
				fn(i)
				y.between()
			}
		}()
	}
	wg.Wait()
}

// yieldAfter bounds how long one goroutine runs Run's tasks back to back
// without yielding. The runtime preempts Go code only after about 10 ms, and
// never inside assembly, so without these yields a goroutine that shares a
// processor with an inference pass (GOMAXPROCS=1, or every P busy) waits up
// to that long for it. With them it waits at most about yieldAfter plus one
// task. At 0.5 ms the cost is one clock read per task and at most 2000
// runtime.Gosched calls per second per goroutine, well under 0.1 % of the
// pass. It is a variable so tests can change it.
var yieldAfter = 500 * time.Microsecond

// yield is runtime.Gosched; tests count its calls.
var yield = runtime.Gosched

// yielder tracks one goroutine's time since it last yielded inside one Run.
type yielder struct{ since time.Time }

func newYielder() yielder { return yielder{since: time.Now()} }

// between is called after every task: it yields once yieldAfter has passed.
func (y *yielder) between() {
	if now := time.Now(); now.Sub(y.since) >= yieldAfter {
		yield()
		y.since = time.Now()
	}
}

// Linear is a weight in PyTorch nn.Linear layout: Out rows of In inputs, so
// Forward computes y = x·Wᵀ + b. Exactly one of W (float32) or Q (int8 with a
// per-output-row Scale) is set. The weights must not change after the first
// Forward: an assembly kernel works on a packed copy made then (or by
// Prepack), which Quantize discards.
type Linear struct {
	Out, In int
	W       []float32
	Q       []int8
	Scale   []float32
	Bias    []float32

	packMu sync.Mutex
	packed atomic.Pointer[packedWeights]
}

// NewLinear validates and wraps float32 weights. bias may be nil.
func NewLinear(out, in int, w, bias []float32) (*Linear, error) {
	if out <= 0 || in <= 0 || len(w) != out*in {
		return nil, fmt.Errorf("tensor: linear weight has %d values, want %dx%d", len(w), out, in)
	}
	if bias != nil && len(bias) != out {
		return nil, fmt.Errorf("tensor: linear bias has %d values, want %d", len(bias), out)
	}
	return &Linear{Out: out, In: in, W: w, Bias: bias}, nil
}

// NewQuantizedLinear wraps int8 weights with per-row scales. bias may be nil.
func NewQuantizedLinear(out, in int, q []int8, scale, bias []float32) (*Linear, error) {
	if out <= 0 || in <= 0 || len(q) != out*in || len(scale) != out {
		return nil, fmt.Errorf("tensor: int8 linear has %d values and %d scales, want %dx%d", len(q), len(scale), out, in)
	}
	if bias != nil && len(bias) != out {
		return nil, fmt.Errorf("tensor: linear bias has %d values, want %d", len(bias), out)
	}
	return &Linear{Out: out, In: in, Q: q, Scale: scale, Bias: bias}, nil
}

// Quantized reports whether the weight uses the int8 path.
func (l *Linear) Quantized() bool { return l.Q != nil }

// Quantize replaces float32 weights with symmetric per-row int8 weights.
func (l *Linear) Quantize() {
	if l.Q != nil {
		return
	}
	l.Q, l.Scale = QuantizeRows(l.W, l.Out, l.In)
	l.W = nil
	l.packed.Store(nil)
}

// QuantizeRows quantizes a rows x cols matrix to int8 with one symmetric scale
// per row: scale = max|w| / 127 (rounded to float32) and q = round-half-even
// of w/scale computed in float64, clamped to [-127, 127]. The rule is
// deterministic, so the Python reference reproduces it bit for bit.
func QuantizeRows(w []float32, rows, cols int) ([]int8, []float32) {
	q := make([]int8, rows*cols)
	scale := make([]float32, rows)
	for r := 0; r < rows; r++ {
		row := w[r*cols : (r+1)*cols]
		var maxAbs float32
		for _, v := range row {
			if a := float32(math.Abs(float64(v))); a > maxAbs {
				maxAbs = a
			}
		}
		if maxAbs == 0 {
			scale[r] = 1
			continue
		}
		s := float32(float64(maxAbs) / 127)
		scale[r] = s
		out := q[r*cols : (r+1)*cols]
		for i, v := range row {
			x := math.RoundToEven(float64(v) / float64(s))
			out[i] = int8(math.Max(-127, math.Min(127, x)))
		}
	}
	return q, scale
}

const (
	blockM = 64 // rows of x per task; a multiple of the 4-row tile
	blockN = 32 // weight rows per task; a multiple of the 4-column tile
)

// Forward writes y (m x Out) = x (m x In) · Wᵀ + b into dst.
func (l *Linear) Forward(dst, x []float32, m int, par Parallel) {
	if len(x) < m*l.In || len(dst) < m*l.Out {
		panic(fmt.Sprintf("tensor: linear %dx%d given x=%d dst=%d for m=%d", l.Out, l.In, len(x), len(dst), m))
	}
	if m <= 0 {
		return
	}
	if mk := par.microkernel(); mk != nil {
		l.forwardPacked(dst, x, m, par, mk)
		return
	}
	mBlocks := (m + blockM - 1) / blockM
	nBlocks := (l.Out + blockN - 1) / blockN
	par.Run(mBlocks*nBlocks, func(task int) {
		mb, nb := task/nBlocks, task%nBlocks
		m0, n0 := mb*blockM, nb*blockN
		m1, n1 := min(m0+blockM, m), min(n0+blockN, l.Out)
		if l.Q != nil {
			gemmBlockQ8(dst, x, l.Q, l.In, l.Out, m0, m1, n0, n1)
			for r := m0; r < m1; r++ {
				row := dst[r*l.Out : (r+1)*l.Out]
				for n := n0; n < n1; n++ {
					row[n] *= l.Scale[n]
				}
			}
		} else {
			gemmBlockF32(dst, x, l.W, l.In, l.Out, m0, m1, n0, n1)
		}
		if l.Bias != nil {
			for r := m0; r < m1; r++ {
				row := dst[r*l.Out : (r+1)*l.Out]
				for n := n0; n < n1; n++ {
					row[n] += l.Bias[n]
				}
			}
		}
	})
}

// MatMulT computes dst (m x n) = a (m x k) · bᵀ where b is n x k. It is the
// portable float32 GEMM used by Linear, exposed for attention-style products;
// it always runs the generic kernel (b changes per call, so there is no
// packed copy to amortise).
func MatMulT(dst, a, b []float32, m, n, k int, par Parallel) {
	mBlocks := (m + blockM - 1) / blockM
	nBlocks := (n + blockN - 1) / blockN
	par.Run(mBlocks*nBlocks, func(task int) {
		mb, nb := task/nBlocks, task%nBlocks
		m0, n0 := mb*blockM, nb*blockN
		gemmBlockF32(dst, a, b, k, n, m0, min(m0+blockM, m), n0, min(n0+blockN, n))
	})
}

func gemmBlockF32(dst, x, w []float32, k, ldd, m0, m1, n0, n1 int) {
	n := n0
	for ; n+4 <= n1; n += 4 {
		w0 := w[n*k : n*k+k]
		w1 := w[(n+1)*k : (n+1)*k+k]
		w2 := w[(n+2)*k : (n+2)*k+k]
		w3 := w[(n+3)*k : (n+3)*k+k]
		r := m0
		for ; r+4 <= m1; r += 4 {
			c := dot4x4(x[r*k:r*k+k], x[(r+1)*k:(r+1)*k+k], x[(r+2)*k:(r+2)*k+k], x[(r+3)*k:(r+3)*k+k], w0, w1, w2, w3)
			for i := 0; i < 4; i++ {
				copy(dst[(r+i)*ldd+n:(r+i)*ldd+n+4], c[4*i:4*i+4])
			}
		}
		for ; r < m1; r++ {
			c := dot1x4(x[r*k:r*k+k], w0, w1, w2, w3)
			copy(dst[r*ldd+n:r*ldd+n+4], c[:])
		}
	}
	for ; n < n1; n++ {
		wn := w[n*k : n*k+k]
		for r := m0; r < m1; r++ {
			dst[r*ldd+n] = dot1x1(x[r*k:r*k+k], wn)
		}
	}
}

// gemmBlockQ8 widens each 4-row int8 weight panel to float32 once per task
// and reuses it across the task's rows of x. float32(q) is exact, so the
// result equals converting inside the dot product (dot4x4q) bit for bit.
func gemmBlockQ8(dst, x []float32, w []int8, k, ldd, m0, m1, n0, n1 int) {
	n := n0
	panel := make([]float32, 4*k)
	for ; n+4 <= n1; n += 4 {
		for i, q := range w[n*k : (n+4)*k] {
			panel[i] = float32(q)
		}
		w0, w1, w2, w3 := panel[:k], panel[k:2*k], panel[2*k:3*k], panel[3*k:]
		r := m0
		for ; r+4 <= m1; r += 4 {
			c := dot4x4(x[r*k:r*k+k], x[(r+1)*k:(r+1)*k+k], x[(r+2)*k:(r+2)*k+k], x[(r+3)*k:(r+3)*k+k], w0, w1, w2, w3)
			for i := 0; i < 4; i++ {
				copy(dst[(r+i)*ldd+n:(r+i)*ldd+n+4], c[4*i:4*i+4])
			}
		}
		for ; r < m1; r++ {
			c := dot1x4(x[r*k:r*k+k], w0, w1, w2, w3)
			copy(dst[r*ldd+n:r*ldd+n+4], c[:])
		}
	}
	for ; n < n1; n++ {
		wn := w[n*k : n*k+k]
		for r := m0; r < m1; r++ {
			dst[r*ldd+n] = dot1x1q(x[r*k:r*k+k], wn)
		}
	}
}

// The microkernels below all accumulate each output as c += a[i]*b[i] for
// i = 0..k-1 in order, so an element's value does not depend on which kernel
// computed it.

func dot4x4(a0, a1, a2, a3, b0, b1, b2, b3 []float32) [16]float32 {
	k := len(a0)
	a1, a2, a3 = a1[:k], a2[:k], a3[:k]
	b0, b1, b2, b3 = b0[:k], b1[:k], b2[:k], b3[:k]
	var c00, c01, c02, c03, c10, c11, c12, c13 float32
	var c20, c21, c22, c23, c30, c31, c32, c33 float32
	for i := 0; i < k; i++ {
		x0, x1, x2, x3 := a0[i], a1[i], a2[i], a3[i]
		y0, y1, y2, y3 := b0[i], b1[i], b2[i], b3[i]
		c00 += x0 * y0
		c01 += x0 * y1
		c02 += x0 * y2
		c03 += x0 * y3
		c10 += x1 * y0
		c11 += x1 * y1
		c12 += x1 * y2
		c13 += x1 * y3
		c20 += x2 * y0
		c21 += x2 * y1
		c22 += x2 * y2
		c23 += x2 * y3
		c30 += x3 * y0
		c31 += x3 * y1
		c32 += x3 * y2
		c33 += x3 * y3
	}
	return [16]float32{c00, c01, c02, c03, c10, c11, c12, c13, c20, c21, c22, c23, c30, c31, c32, c33}
}

func dot1x4(a, b0, b1, b2, b3 []float32) [4]float32 {
	k := len(a)
	b0, b1, b2, b3 = b0[:k], b1[:k], b2[:k], b3[:k]
	var c0, c1, c2, c3 float32
	for i := 0; i < k; i++ {
		x := a[i]
		c0 += x * b0[i]
		c1 += x * b1[i]
		c2 += x * b2[i]
		c3 += x * b3[i]
	}
	return [4]float32{c0, c1, c2, c3}
}

func dot1x1(a, b []float32) float32 {
	b = b[:len(a)]
	var c float32
	for i := range a {
		c += a[i] * b[i]
	}
	return c
}

// Dot returns the sequential float32 dot product of a and b[:len(a)].
func Dot(a, b []float32) float32 { return dot1x1(a, b) }

func dot1x1q(a []float32, b []int8) float32 {
	b = b[:len(a)]
	var c float32
	for i := range a {
		c += a[i] * float32(b[i])
	}
	return c
}
